return function rootGuardRows(sources, selections, Rust) {
 const rows=[], proof=[];
 function whole(row,code,start,end,label){
  const span=code.slice(start,end+1);
  let cut=span.indexOf("\n");
  if(cut<0){cut=span.indexOf("{");if(cut>=0)cut++;else{const x=/^(?:pub(?:\([^)]*\))?\s+)?(?:struct|enum)\s+\w+/.exec(span);cut=x?.[0].length||-1;}}
  if(cut<=0||cut>=span.length)throw Error("complete whole-span split "+label);
  const left=span.slice(0,cut).trim(),right=span.slice(cut);
  if(!left||!right||Rust.positions(code,span).length!==1)throw Error("unique complete span "+label);
  row.required_order.push([left,right]);
 }
 for(const selection of selections){
  const raw=sources[selection.path],code=Rust.code(raw),row={path:selection.path,required:[],forbidden:[],required_order:[],required_function_order:[]};
  const wholeUsed=new Set(),impls=[];
  for(const match of code.matchAll(/\bimpl\b[^;{]*\{/g)){const end=Rust.itemEnd(code,match.index);if(end!==null)impls.push({start:match.index,end});}
  const fns=[...code.matchAll(/\bfn\s+([A-Za-z_]\w*)/g)].filter(m=>!selection.functions||selection.functions.includes(m[1]));
  for(const fn of fns){
   const name=fn[1],marker="fn "+name+"(",start=fn.index,end=Rust.itemEnd(code,start);
   if(end===null||code[end]!=="}")throw Error("function extent "+selection.path+" "+name);
   if(name!=="drop"&&code.startsWith(marker,start)&&Rust.positions(code,marker).length===1){
    const extent=Rust.fnExtent(code,marker);let sequence=extent.body.split("\n").map(s=>s.trim()).filter(Boolean);
    if(sequence.length<2){const brace=extent.body.indexOf("{");sequence=[extent.body.slice(0,brace+1),extent.body.slice(brace+1)];}
    if(sequence.some(s=>!s))throw Error("nonempty sequence "+name);
    const top_level=sequence.filter(s=>s.length>=3&&Rust.positions(extent.body,s).length===1).filter(s=>{const p=extent.body.slice(0,extent.body.indexOf(s));return(p.match(/\{/g)||[]).length-(p.match(/\}/g)||[]).length===1;});
    row.required_function_order.push({function:marker,sequence,...(top_level.length?{top_level}:{})});
    const line=raw.slice(raw.lastIndexOf("\n",start)+1,start+marker.length).trim();if(!row.required.includes(line))row.required.push(line);
   }else{
    const parent=impls.filter(x=>x.start<start&&x.end>=end).sort((a,b)=>b.start-a.start)[0];
    const span=parent||{start,end},key=span.start+":"+span.end;
    if(!wholeUsed.has(key)){whole(row,code,span.start,span.end,name);wholeUsed.add(key);}
   }
  }
  if(selection.allStructures){
   for(const match of code.matchAll(/(?:pub(?:\([^)]*\))?\s+)?\b(?:struct|enum)\s+[A-Za-z_]\w*/g)){
    const start=match.index,end=Rust.itemEnd(code,start);if(end===null)throw Error("type extent");
    const key=start+":"+end;if(!wholeUsed.has(key)){whole(row,code,start,end,match[0]);wholeUsed.add(key);}
   }
  }
  for(const marker of selection.structures||[]){
   const hits=Rust.positions(code,marker);if(hits.length!==1)throw Error("unique declared structure "+marker);
   const start=hits[0],end=Rust.itemEnd(code,start),key=start+":"+end;if(!wholeUsed.has(key)){whole(row,code,start,end,marker);wholeUsed.add(key);}
  }
  for(const marker of selection.required||[])if(!row.required.includes(marker))row.required.push(marker);
  const checked=Rust.project(row,raw);
  proof.push({path:selection.path,unique_function_guards:checked.functions.length,complete_span_guards:row.required_order.length,code_markers:row.required_function_order.reduce((n,f)=>n+f.sequence.length,0),top_level_markers:row.required_function_order.reduce((n,f)=>n+(f.top_level||[]).length,0)});
  rows.push(row);
 }
 return{rows,proof};
}

